OPEN_ROAD_NATIVE_ELEVATION_ENABLED = not PLATFORM_ENABLED and str(WORKSPACE_SETTINGS.get('mode', '')) == 'open_road' and (len(OPEN_ROAD_ELEVATION_POINTS) >= 2)
NATIVE_SPLINE_Z = float(WORKSPACE_SETTINGS.get('spline_z_m', 1.2))
TRACK_BASE_Z = float(PLATFORM_SETTINGS.get('top_z_m', 0.0)) if PLATFORM_ENABLED else NATIVE_SPLINE_Z
ACTOR_HANDLES = {}
OPEN_ROAD_QCAR_SPAWN_CLEARANCE_M = 1.5

def apply_environment_settings(qlabs):
    settings = TRACK_DATA.get('environment', {}) or {}
    if not bool(settings.get('enabled', True)):
        return
    env = QLabsEnvironmentOutdoors(qlabs)
    weather_name = str(settings.get('weather', 'clear_skies'))
    weather_map = {'clear_skies': env.CLEAR_SKIES, 'partly_cloudy': env.PARTLY_CLOUDY, 'cloudy': env.CLOUDY, 'overcast': env.OVERCAST, 'foggy': env.FOGGY, 'light_rain': env.LIGHT_RAIN, 'rain': env.RAIN, 'thunderstorm': env.THUNDERSTORM, 'light_snow': env.LIGHT_SNOW, 'snow': env.SNOW, 'blizzard': env.BLIZZARD}
    env.set_weather_preset(weather_map.get(weather_name, env.CLEAR_SKIES))
    env.set_time_of_day(max(0.0, min(24.0, float(settings.get('time_of_day', 12.0)))))

def project_scale():
    return float(TRACK_DATA.get('project', {}).get('scale_factor', 1.0))

def editor_yaw_to_qlabs_radians(editor_rotation_deg):
    return math.radians(-float(editor_rotation_deg))

def open_road_surface_z_at_world_xy(x, y):
    """Interpolate measured Open Road Z from the nearest recorded XY segment.

    The logger measured one driven lane.  For nearby roadside actors we use the
    nearest segment as a terrain/road-height proxy.  At a true vertically
    overlapping road crossing, XY alone cannot identify upper vs lower deck;
    the object's Base Z remains available as a manual offset for that case.
    """
    if not OPEN_ROAD_NATIVE_ELEVATION_ENABLED:
        return TRACK_BASE_Z
    px = float(x)
    py = float(y)
    best_distance_sq = float('inf')
    best_z = TRACK_BASE_Z
    for index in range(len(OPEN_ROAD_ELEVATION_POINTS) - 1):
        a = OPEN_ROAD_ELEVATION_POINTS[index]
        b = OPEN_ROAD_ELEVATION_POINTS[index + 1]
        ax, ay, az = (float(a[0]), float(a[1]), float(a[2]))
        bx, by, bz = (float(b[0]), float(b[1]), float(b[2]))
        dx = bx - ax
        dy = by - ay
        denominator = dx * dx + dy * dy
        if denominator <= 1e-12:
            t = 0.0
        else:
            t = ((px - ax) * dx + (py - ay) * dy) / denominator
            t = max(0.0, min(1.0, t))
        qx = ax + t * dx
        qy = ay + t * dy
        distance_sq = (px - qx) ** 2 + (py - qy) ** 2
        if distance_sq < best_distance_sq:
            best_distance_sq = distance_sq
            best_z = az + t * (bz - az)
    return float(best_z)

def surface_z_at_world_xy(x, y):
    if OPEN_ROAD_NATIVE_ELEVATION_ENABLED:
        return open_road_surface_z_at_world_xy(x, y)
    return TRACK_BASE_Z

def _register_actor_handle(obj, actor):
    """Expose an actor by both stable object id and readable identifier."""
    object_id = str(obj.get('id', ''))
    identifier = str(obj.get('identifier', ''))
    if object_id:
        ACTOR_HANDLES[object_id] = actor
    if identifier:
        ACTOR_HANDLES[identifier] = actor

def spawn_qcar2(qlabs):
    starts = [obj for obj in TRACK_DATA.get('objects', []) if obj.get('type') == 'qcar2_start']
    if not starts:
        print('No QCar2 Start marker in track; roads only.')
        return None
    obj = starts[0]
    scale = project_scale()
    world_x = float(obj.get('x', 0.0)) * scale
    world_y = float(obj.get('y', 0.0)) * scale
    qcar = QLabsQCar2(qlabs)
    qcar.spawn_id(actorNumber=0, location=[world_x, world_y, surface_z_at_world_xy(world_x, world_y) + (OPEN_ROAD_QCAR_SPAWN_CLEARANCE_M * scale if OPEN_ROAD_NATIVE_ELEVATION_ENABLED else 2.0 * scale)], rotation=[0, 0, editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))], scale=[scale, scale, scale], configuration=0, waitForConfirmation=True)
    _register_actor_handle(obj, qcar)
    return qcar

def main():
    print('Connecting to QLabs...')
    qlabs = QuanserInteractiveLabs()
    if not qlabs.open('localhost'):
        print('Unable to connect to QLabs.')
        print('Open QLabs in the Open Road workspace and try again.')
        sys.exit(1)
    print('Connected to QLabs.')
    if OPEN_ROAD_NATIVE_ELEVATION_ENABLED:
        print('Open Road measured elevation enabled:', len(OPEN_ROAD_ELEVATION_POINTS), 'XYZ samples')
    qlabs.destroy_all_spawned_actors()
    QLabsRealTime().terminate_all_real_time_models()
    time.sleep(0.5)
    apply_environment_settings(qlabs)
    objects = TRACK_DATA.get('objects', [])
    qcar = spawn_qcar2(qlabs)
    if qcar is not None:
        QLabsRealTime().start_real_time_model(rtmodels.QCAR2)
        time.sleep(0.5)
        starts = [obj for obj in objects if obj.get('type') == 'qcar2_start']
        camera_view = str(starts[0].get('camera_view', 'third_person')) if starts else 'third_person'
        if camera_view == 'first_person':
            qcar.possess(QLabsQCar2.CAMERA_CSI_FRONT)
        else:
            qcar.possess(QLabsQCar2.CAMERA_TRAILING)
    print('QLabs track created. Project scale = ' + str(TRACK_DATA.get('project', {}).get('scale_name', '1:1')))
if __name__ == '__main__':
    main()
